func (q *Queries) ListTrackingDownloadTasks(ctx context.Context) ([]DownloadTask, error) {
	rows, err := q.db.Query(ctx, listTrackingDownloadTasks)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DownloadTask
	for rows.Next() {
		var i DownloadTask
		if err := rows.Scan(
			&i.ID,
			&i.OperationID,
			&i.ClientID,
			&i.CandidateID,
			&i.InfoHash,
			&i.State,
			&i.SavePath,
			&i.ContentPath,
			&i.Progress,
			&i.TotalBytes,
			&i.DownloadedBytes,
			&i.ReconcileCount,
			&i.Error,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.FinishedAt,
			&i.OrganizationState,
			&i.OrganizationReason,
			&i.TransferPlanID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

