const recoverExpiredOrganizationJobs = `-- name: RecoverExpiredOrganizationJobs :execrows
UPDATE job SET state=CASE WHEN attempts>=max_attempts THEN 'dead' ELSE 'queued' END,
 lease_owner=NULL,lease_until=NULL,updated_at=statement_timestamp()
WHERE kind='download_organization' AND state='running' AND lease_until<=clock_timestamp()
`

func (q *Queries) RecoverExpiredOrganizationJobs(ctx context.Context) (int64, error) {
	result, err := q.db.Exec(ctx, recoverExpiredOrganizationJobs)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const releaseCancelledOrganizationReservations = `-- name: ReleaseCancelledOrganizationReservations :exec
UPDATE unit_reservation r SET state='released',updated_at=clock_timestamp()
WHERE r.operation_id=$1 AND r.state IN ('reserved','dispatched') AND NOT EXISTS(SELECT 1 FROM download_requirement d WHERE d.operation_id=r.operation_id AND d.root_id=r.root_id AND d.unit_id=r.unit_id AND d.state='pending')
`

func (q *Queries) ReleaseCancelledOrganizationReservations(ctx context.Context, operationID uuid.UUID) error {
	_, err := q.db.Exec(ctx, releaseCancelledOrganizationReservations, operationID)
	return err
}

